import{_ as e,o as n,c,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"01 — Cấu trúc Tổ chức & Kiến trúc Không gian Lai (Organization Structure & Hybrid Workspace Architecture)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/01-organization-structure.md","filePath":"ba/01-organization-structure.md"}'),a={name:"ba/01-organization-structure.md"};function d(i,t,s,h,r,l){return n(),c("div",null,[...t[0]||(t[0]=[o(`<h1 id="_01-—-cau-truc-to-chuc-kien-truc-khong-gian-lai-organization-structure-hybrid-workspace-architecture" tabindex="-1">01 — Cấu trúc Tổ chức &amp; Kiến trúc Không gian Lai (Organization Structure &amp; Hybrid Workspace Architecture) <a class="header-anchor" href="#_01-—-cau-truc-to-chuc-kien-truc-khong-gian-lai-organization-structure-hybrid-workspace-architecture" aria-label="Permalink to &quot;01 — Cấu trúc Tổ chức &amp; Kiến trúc Không gian Lai (Organization Structure &amp; Hybrid Workspace Architecture)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Index</a> · <a href="./README.html">← 00 - Overview</a> · <a href="./02-authentication-profile.html">Tiếp: 02 - Authentication &amp; Profile →</a></p><hr><h2 id="_1-kien-truc-đa-tang-chuan-user-→-agency-personal-hub-→-workspace" tabindex="-1">1. Kiến trúc Đa tầng Chuẩn (<code>User → Agency / Personal Hub → Workspace</code>) <a class="header-anchor" href="#_1-kien-truc-đa-tang-chuan-user-→-agency-personal-hub-→-workspace" aria-label="Permalink to &quot;1. Kiến trúc Đa tầng Chuẩn (\`User → Agency / Personal Hub → Workspace\`)&quot;">​</a></h2><p>BrandHub tổ chức dữ liệu và phân quyền theo mô hình đa thuê bao (multi-tenant) 3 tầng, hỗ trợ đồng thời cả <strong>Công ty Truyền thông (<code>Agency B2B</code>)</strong> và <strong>Không gian Cá nhân (<code>Personal Studio</code>)</strong> trên cùng một cấu trúc cơ sở dữ liệu:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                      TẦNG 1: TÀI KHOẢN NGƯỜI DÙNG (USER)                   │</span></span>
<span class="line"><span>│  Mỗi tài khoản xác thực (Owner / Manager / Creator / Client / Admin)       │</span></span>
<span class="line"><span>│  có thể tham gia nhiều Agency và sở hữu 1 Personal Hub riêng biệt.         │</span></span>
<span class="line"><span>└───────────────────┬────────────────────────────────────┬───────────────────┘</span></span>
<span class="line"><span>                    │                                    │</span></span>
<span class="line"><span>                    ▼                                    ▼</span></span>
<span class="line"><span>┌───────────────────────────────────────┐  ┌─────────────────────────────────┐</span></span>
<span class="line"><span>│     TẦNG 2A: AGENCY B2B (CÔNG TY)     │  │  TẦNG 2B: PERSONAL HUB (STUDIO) │</span></span>
<span class="line"><span>│ • Đại diện cho 1 công ty truyền thông │  │ • Bản ghi Agency cá nhân tự tạo │</span></span>
<span class="line"><span>│ • Chủ sở hữu giữ vai trò: Owner       │  │   1 chạm (logoIcon =            │</span></span>
<span class="line"><span>│ • Có Ví AI Credit tổng &amp; Gói cước     │  │   &quot;personal-studio&quot;)            │</span></span>
<span class="line"><span>│ • Quản lý danh sách nhân sự công ty   │  │ • Chủ sở hữu giữ vai trò: Owner │</span></span>
<span class="line"><span>│   &amp; danh mục Gói truyền thông mẫu     │  │ • Có sẵn Ví AI Credit &amp; Gói     │</span></span>
<span class="line"><span>└───────────────────┬───────────────────┘  └────────────────┬────────────────┘</span></span>
<span class="line"><span>                    │                                       │</span></span>
<span class="line"><span>                    ▼                                       ▼</span></span>
<span class="line"><span>┌───────────────────────────────────────┐  ┌─────────────────────────────────┐</span></span>
<span class="line"><span>│ TẦNG 3A: WORKSPACE (mode = &quot;AGENCY&quot;)  │  │ TẦNG 3B: WORKSPACE (&quot;PERSONAL&quot;) │</span></span>
<span class="line"><span>│ • Đại diện cho 1 Thương hiệu Client   │  │ • Đại diện cho Dự án cá nhân,   │</span></span>
<span class="line"><span>│ • Bắt buộc có 1 Manager               │  │   Kênh MXH riêng hoặc Bài tập   │</span></span>
<span class="line"><span>│ • Có thể mời nhiều Creator &amp; 1 Client │  │ • Chủ không gian là Manager     │</span></span>
<span class="line"><span>│ • Quy trình 3 bước:                   │  │ • Không cần MediaPackage/Client │</span></span>
<span class="line"><span>│   Gói dịch vụ → Chiến dịch → Task     │  │ • Tạo Chiến dịch tự do hoặc     │</span></span>
<span class="line"><span>│ • Phê duyệt 2 cấp:                    │  │   Tạo Task độc lập 8 loại       │</span></span>
<span class="line"><span>│   Manager/Supervisor → Client         │  │ • Tự duyệt 1 chạm (Self-Approve)│</span></span>
<span class="line"><span>└───────────────────────────────────────┘  └─────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_2-đinh-nghia-6-vai-tro-he-thong-chuan-6-canonical-roles" tabindex="-1">2. Định nghĩa 6 Vai trò Hệ thống Chuẩn (6 Canonical Roles) <a class="header-anchor" href="#_2-đinh-nghia-6-vai-tro-he-thong-chuan-6-canonical-roles" aria-label="Permalink to &quot;2. Định nghĩa 6 Vai trò Hệ thống Chuẩn (6 Canonical Roles)&quot;">​</a></h2><p>Theo quy chuẩn bắt buộc tại <code>AGENTS.md</code>, toàn hệ thống <strong>chỉ sử dụng đúng 6 tên Role chuẩn</strong> dưới đây (không tồn tại các tên như <code>USER</code>, <code>MEMBER</code>, <code>Account Manager</code> hay <code>Brand Client</code>):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Role chuẩn</th><th style="text-align:left;">Enum Code</th><th style="text-align:left;">Cấp định danh</th><th style="text-align:left;">Mô tả &amp; Quyền hạn thực tế trong hệ thống</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>Guest</code></strong></td><td style="text-align:left;"><code>GUEST</code></td><td style="text-align:left;">Công khai (Chưa đăng nhập)</td><td style="text-align:left;">Người dùng chưa đăng nhập hoặc người truy cập qua đường dẫn chia sẻ công khai (<code>/s/:token</code>). Được phép đăng ký, đăng nhập, khôi phục mật khẩu, nộp phản hồi khảo sát công khai (<code>/public/surveys/:token</code>) và xem chỉ-đọc tài nguyên được chia sẻ qua <code>ShareLink</code>.</td></tr><tr><td style="text-align:left;"><strong><code>Owner</code></strong></td><td style="text-align:left;"><code>OWNER</code></td><td style="text-align:left;">Cấp <code>Agency</code> (<code>agencies.owner_id</code>)</td><td style="text-align:left;">Người sáng lập / chủ sở hữu của một <code>Agency</code> (hoặc chủ sở hữu <code>Personal Hub</code> cá nhân). Toàn quyền cập nhật hồ sơ công ty, mời/gỡ thành viên công ty, tạo/xóa/lưu trữ <code>Workspace</code>, cấu hình trần AI Credit cho từng <code>Workspace</code> (<code>workspaceLimit</code>), nâng cấp gói cước (<code>Subscription</code>), thanh toán qua SePay và tạo Gói truyền thông mẫu (<code>MediaPackage</code>).</td></tr><tr><td style="text-align:left;"><strong><code>Manager</code></strong></td><td style="text-align:left;"><code>MANAGER</code></td><td style="text-align:left;">Cấp <code>Workspace</code> (<code>workspace_members</code>)</td><td style="text-align:left;">Người điều hành trực tiếp một <code>Workspace</code>. Mỗi Workspace luôn có ít nhất 1 <code>Manager</code>. Trong Workspace <code>AGENCY</code>, <code>Manager</code> chốt Gói dịch vụ, lập &amp; triển khai Chiến dịch, phân công Công việc/Subtask, duyệt nội bộ các phần (<code>INTERNAL_APPROVED</code>), quản lý tư liệu, gửi bản tin và kết nối MXH. Trong Workspace <code>PERSONAL</code>, chủ không gian giữ đồng thời vai trò <code>Owner</code> và <code>Manager</code>, có thêm quyền <strong>Tự duyệt 1 chạm (<code>Self-Approve</code>)</strong>.</td></tr><tr><td style="text-align:left;"><strong><code>Creator</code></strong></td><td style="text-align:left;"><code>CREATOR</code></td><td style="text-align:left;">Cấp <code>Workspace</code> (<code>workspace_members</code>)</td><td style="text-align:left;">Thành viên thực thi sáng tạo trong <code>Workspace</code> (nhân sự nội bộ của Agency hoặc bạn cùng nhóm được mời vào Workspace <code>PERSONAL</code>). Được giao <code>Task</code> cha (với tư cách Điều phối viên) hoặc <code>Subtask</code> theo vai trò chuyên môn (<code>POST_CONTENT</code>, <code>POST_MEDIA</code>, <code>VIDEO_SCRIPT</code>, <code>EVENT_AGENDA</code>...), sử dụng AI Studio để tạo nội dung và nộp duyệt từng phần (<code>TaskSection</code>).</td></tr><tr><td style="text-align:left;"><strong><code>Client</code></strong></td><td style="text-align:left;"><code>CLIENT</code></td><td style="text-align:left;">Cấp <code>Workspace</code> (<code>workspace_members</code>)</td><td style="text-align:left;">Khách hàng thương hiệu trong Workspace có <code>workspaceMode = &quot;AGENCY&quot;</code>. Truy cập <code>Client Portal</code> để xem tiến độ, tạo yêu cầu nội dung (<code>Content Request</code>), kết nối tài khoản MXH của thương hiệu, và duyệt/trả lại các phần sản phẩm đầu ra (<code>OUTPUT</code> sections → <code>CLIENT_APPROVED</code>). Không xuất hiện trong Workspace <code>PERSONAL</code>.</td></tr><tr><td style="text-align:left;"><strong><code>Admin</code></strong></td><td style="text-align:left;"><code>ADMIN</code></td><td style="text-align:left;">Toàn hệ thống (<code>users.system_role</code>)</td><td style="text-align:left;">Quản trị viên vận hành nền tảng BrandHub (<code>/admin/*</code>). Quản lý danh sách người dùng, hàng đợi kiểm duyệt nội dung vi phạm (<code>Content Moderation Queue</code>), cấu hình gói cước &amp; bảng giá AI Credit, điều khiển đường ống thu thập xu hướng (<code>Trend Crawler Pipeline</code>), theo dõi sức khỏe hệ thống và xuất báo cáo doanh thu.</td></tr></tbody></table><hr><h2 id="_3-quy-tac-đa-vai-tro-theo-ngu-canh-contextual-multi-role-rules" tabindex="-1">3. Quy tắc Đa Vai trò theo Ngữ cảnh (Contextual Multi-Role Rules) <a class="header-anchor" href="#_3-quy-tac-đa-vai-tro-theo-ngu-canh-contextual-multi-role-rules" aria-label="Permalink to &quot;3. Quy tắc Đa Vai trò theo Ngữ cảnh (Contextual Multi-Role Rules)&quot;">​</a></h2><p>Một tài khoản người dùng vật lý (<code>User</code>) có thể giữ các vai trò khác nhau tùy theo ngữ cảnh đang mở:</p><ol><li><strong>Giữa các Agency khác nhau</strong>: <ul><li>Người dùng A có thể là <strong><code>Owner</code></strong> của <code>Personal Studio</code> cá nhân của mình, đồng thời là <strong><code>Creator</code></strong> hoặc <strong><code>Manager</code></strong> được mời vào <code>Agency X</code> (công ty nơi họ làm việc).</li></ul></li><li><strong>Giữa các Workspace trong cùng một Agency</strong>: <ul><li>Nhân sự B thuộc <code>Agency X</code> có thể được bổ nhiệm làm <strong><code>Manager</code></strong> tại <code>Workspace 1</code> (dự án thương hiệu A), nhưng chỉ là <strong><code>Creator</code></strong> hỗ trợ viết bài tại <code>Workspace 2</code> (dự án thương hiệu B).</li></ul></li><li><strong>Trong cùng một Workspace</strong>: <ul><li>Mỗi người dùng chỉ có <strong>1 bản ghi vai trò (<code>WorkspaceRole</code>: <code>MANAGER</code>, <code>CREATOR</code>, hoặc <code>CLIENT</code>)</strong> trong một <code>Workspace</code> cụ thể (<code>UNIQUE (workspace_id, user_id)</code>).</li><li>Riêng <code>Owner</code> của Agency chứa Workspace đó mặc định có quyền quản trị cấp cao trên mọi Workspace thuộc Agency của mình; khi tạo Workspace ở chế độ <code>PERSONAL</code>, <code>Owner</code> được gán trực tiếp làm <code>MANAGER</code> của Workspace đó.</li></ul></li></ol><hr><h2 id="_4-so-sanh-chi-tiet-che-đo-agency-va-che-đo-personal" tabindex="-1">4. So sánh Chi tiết Chế độ <code>AGENCY</code> và Chế độ <code>PERSONAL</code> <a class="header-anchor" href="#_4-so-sanh-chi-tiet-che-đo-agency-va-che-đo-personal" aria-label="Permalink to &quot;4. So sánh Chi tiết Chế độ \`AGENCY\` và Chế độ \`PERSONAL\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tiêu chí Nghiệp vụ</th><th style="text-align:left;">Chế độ <code>AGENCY</code> (<code>workspaceMode = &quot;AGENCY&quot;</code>)</th><th style="text-align:left;">Chế độ <code>PERSONAL</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Cách khởi tạo</strong></td><td style="text-align:left;"><code>Owner</code> tạo <code>Agency</code> → mời nhân sự → tạo <code>Workspace</code> → chọn <code>Manager</code> từ danh sách nhân sự.</td><td style="text-align:left;">Bấm 1 chạm <strong>&quot;Không gian Cá nhân (Personal Studio)&quot;</strong> (<code>POST /api/v1/workspaces/personal/bootstrap</code>) hoặc chọn chế độ <code>PERSONAL</code> khi tạo Workspace mới (tự gán bản thân làm <code>Manager</code>).</td></tr><tr><td style="text-align:left;"><strong>Bước 1: Gói dịch vụ (<code>Media Package</code>)</strong></td><td style="text-align:left;"><strong>Bắt buộc</strong>: Phải gắn <code>WorkspaceMediaPackage</code> và chốt gói trước khi triển khai chiến dịch.</td><td style="text-align:left;"><strong>Bỏ qua</strong>: Ẩn khỏi thanh Tiến trình. Hệ thống tự cấp ngầm gói khung nội bộ không giới hạn nếu người dùng muốn lập Chiến dịch.</td></tr><tr><td style="text-align:left;"><strong>Bước 2: Chiến dịch (<code>Media Campaign</code>)</strong></td><td style="text-align:left;">Khởi tạo từ các hạng mục trong Gói dịch vụ đã chốt; kiểm tra chặt số lượng hạng mục theo gói.</td><td style="text-align:left;"><strong>Tùy chọn &amp; Tự do</strong>: Có thể lập Chiến dịch cá nhân với bất kỳ số lượng hạng mục nào thuộc 8 loại <code>TaskType</code>, hoặc bỏ qua để tạo Task trực tiếp.</td></tr><tr><td style="text-align:left;"><strong>Bước 3: Tạo Công việc (<code>Task</code>)</strong></td><td style="text-align:left;">Sinh từ khi <code>deploy</code> Chiến dịch, từ <code>Content Request</code> của <code>Client</code>, hoặc do <code>Manager</code> tạo.</td><td style="text-align:left;">Hỗ trợ thêm nút <strong>&quot;+ Tạo công việc mới&quot; (<code>Standalone Task</code>)</strong> tạo trực tiếp đủ 8 loại <code>TaskType</code> ngay tại bảng Công việc hoặc từ <code>Personal Quick Launchpad</code>.</td></tr><tr><td style="text-align:left;"><strong>Quy trình Phê duyệt (<code>Approval Flow</code>)</strong></td><td style="text-align:left;">Mặc định 2 cấp: <code>Creator</code> nộp → <code>Manager</code>/<code>Supervisor</code> duyệt nội bộ (<code>INTERNAL_APPROVED</code>) → <code>Client</code> duyệt đầu ra (<code>CLIENT_APPROVED</code>).</td><td style="text-align:left;">Mặc định <code>requiresClientApproval = false</code>. Hỗ trợ nút <strong>Tự duyệt 1 chạm (<code>Self-Approve</code>)</strong> đưa toàn bộ các phần sang <code>INTERNAL_APPROVED</code> và đóng Task <code>FINISHED</code> (<code>APPROVED</code>) tức thì.</td></tr><tr><td style="text-align:left;"><strong>Cộng tác Nhóm (<code>Team Collaboration</code>)</strong></td><td style="text-align:left;">Đầy đủ <code>Owner</code>, <code>Manager</code>, nhiều <code>Creator</code> và <code>Client</code>.</td><td style="text-align:left;">Chủ không gian (<code>Owner</code>/<code>Manager</code>) có thể làm 1 mình (Solo) hoặc mời thêm bạn cùng nhóm làm <strong><code>Creator</code></strong> để chia <code>Subtask</code> theo vai trò (rất phù hợp cho nhóm đồ án sinh viên / nhóm freelancer).</td></tr><tr><td style="text-align:left;"><strong>Thanh điều hướng (<code>Sidebar</code>) &amp; <code>Dashboard</code></strong></td><td style="text-align:left;">Hiển thị đầy đủ 3 bước tiến trình, <code>Cổng Khách hàng</code>, <code>Hồ sơ Khách hàng</code>, <code>Yêu cầu nội dung</code>, <code>PackageStatusBanner</code>.</td><td style="text-align:left;">Rút gọn còn 2 bước tiến trình luôn mở sẵn; ẩn các menu của <code>Client</code>; hiển thị <strong>Bệ phóng Sáng tạo Cá nhân (<code>Personal Quick Launchpad</code>)</strong>.</td></tr><tr><td style="text-align:left;"><strong>Chuyển đổi qua lại (<code>Mode Switching</code>)</strong></td><td style="text-align:left;">Có thể chuyển về <code>PERSONAL</code> nếu trong Workspace chưa có <code>Client</code> đang hoạt động (AC5).</td><td style="text-align:left;">Có thể bấm <strong>&quot;Nâng cấp sang chế độ Agency&quot;</strong> bất kỳ lúc nào trong Cài đặt mà <strong>giữ nguyên 100% dữ liệu</strong> (AC4).</td></tr></tbody></table><hr><h2 id="_5-quy-tac-chia-se-cong-khai-cho-guest-sharelink-architecture" tabindex="-1">5. Quy tắc Chia sẻ Công khai cho <code>Guest</code> (<code>ShareLink</code> Architecture) <a class="header-anchor" href="#_5-quy-tac-chia-se-cong-khai-cho-guest-sharelink-architecture" aria-label="Permalink to &quot;5. Quy tắc Chia sẻ Công khai cho \`Guest\` (\`ShareLink\` Architecture)&quot;">​</a></h2><p>Ngoài các thành viên có tài khoản trong Workspace, hệ thống hỗ trợ chia sẻ chỉ-đọc (read-only) ra bên ngoài cho <strong><code>Guest</code></strong> thông qua thực thể <code>ShareLink</code> (<code>/s/:token</code>):</p><ul><li>Chỉ <strong><code>Owner</code></strong> và <strong><code>Manager</code></strong> của Workspace mới có quyền tạo hoặc thu hồi (<code>revoke</code>) đường dẫn chia sẻ công khai.</li><li>Các loại tài nguyên hỗ trợ chia sẻ công khai: <ol><li><code>MEDIA_PACKAGE</code> — Bảng đề xuất gói dịch vụ truyền thông.</li><li><code>POST</code> — Bản xem trước bài đăng mạng xã hội kèm hình ảnh/video.</li><li><code>DOCUMENT</code> / <code>FOLDER</code> — Tài liệu hoặc thư mục tư liệu trong Thư viện (<code>Material</code>).</li></ol></li><li>Ngoài ra, công việc loại <code>SURVEY</code> và <code>WORKSHOP</code> có đường dẫn biểu mẫu công khai riêng (<code>/public/surveys/:token</code>) để <code>Guest</code> gửi câu trả lời khảo sát hoặc đăng ký tham dự.</li></ul>`,21)])])}const p=e(a,[["render",d]]);export{u as __pageData,p as default};
